/// The extended error codes this specification declares (SPEC §7.3 item 9,
/// §8.5), in declaration order. Empty when it declares none.
pub const ERROR_CODES: &[crate::DeclaredErrorCode] = &[
    error_codes::DOES_NOT_VERIFY,
    error_codes::UNKNOWN_SUITE,
    error_codes::NOT_FOR_THIS_APPLICATION,
];
/// One constant per extended error code this specification declares
/// (SPEC §7.3 item 9), named for its local part.
///
/// Emit these rather than a string literal: the code is read from the
/// specification, so it cannot name a code the specification never
/// declared.
pub mod error_codes {
    /// `vetting/attestation:doesNotVerify`
    ///
    /// The attestation does not verify under the community's published parameters, or is not bound to the card the applicant showed.
    ///
    /// Declared `retryable: false`.
    pub const DOES_NOT_VERIFY: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vetting/attestation:doesNotVerify",
        retryable: false,
    };
    /// `vetting/attestation:unknownSuite`
    ///
    /// `suite` is not one this applicant implements. It cannot be mixed with attestations under another suite.
    ///
    /// Declared `retryable: false`.
    pub const UNKNOWN_SUITE: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vetting/attestation:unknownSuite",
        retryable: false,
    };
    /// `vetting/attestation:notForThisApplication`
    ///
    /// `meta.community` or `meta.requirementsDigest` is not the criterion this applicant is gathering for.
    ///
    /// Declared `retryable: false`.
    pub const NOT_FOR_THIS_APPLICATION: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vetting/attestation:notForThisApplication",
        retryable: false,
    };
}
#[cfg(test)]
mod conformance {
    //! Round-trip tests harvested from the spec's `spec.md`,
    //! plus a `rejects_invalid_examples` test for any fixtures
    //! in `payload.invalid-examples.json` (validate feature).
    #[test]
    fn request_example_1() {
        const JSON: &str = "{\n  \"id\": \"urn:uuid:00000000-0000-4000-8000-000000000001\",\n  \"type\": \"https://trusttasks.org/spec/vetting/attestation/0.1#request\",\n  \"issuer\": \"did:example:vetter\",\n  \"recipient\": \"did:example:applicant\",\n  \"issuedAt\": \"2026-09-20T14:31:00Z\",\n  \"threadId\": \"urn:uuid:00000000-0000-4000-8000-0000000000ff\",\n  \"payload\": {\n    \"suite\": \"ps-ddh-bls12381\",\n    \"attestation\": \"zBbsywyzdGiuJ3aCc147SQheEgDJFJHkgNKctAcZPqHkJqPcYTwKcWQV6wYqPnB1e9N\",\n    \"meta\": {\n      \"community\": \"did:example:community\",\n      \"requirementsDigest\": \"zQmdmF2WvyXF9dgZeb2W2VxxwYeSzqN3fBykoLTkru5QUYE\",\n      \"method\": \"inPerson\",\n      \"claimsVerified\": [\"name.legal\"],\n      \"livenessConfirmed\": true,\n      \"declaredRelationship\": \"none\",\n      \"identityCommitment\": \"zQmPRccGTPKwUUB8nUdSGuK7oN8Ht7c6iEDsLqdK7LNsxKz\",\n      \"cardDigestMultibase\": \"zQmRnZq46vDQnAzSuEnWz3zvfQoigbe23KtSp6S1Vm1UXuL\",\n      \"validFrom\": \"2026-09-20\",\n      \"validUntil\": \"2027-01-18\",\n      \"tokenLabel\": \"token/2026-09\",\n      \"tokenSerial\": \"zBKHjA2kQWBpQPgwiHBG1DrzCykjsvdMfnKBYrhiM4STW\"\n    },\n    \"token\": {\n      \"label\": \"token/2026-09\",\n      \"serial\": \"zBKHjA2kQWBpQPgwiHBG1DrzCykjsvdMfnKBYrhiM4STW\",\n      \"shown\": \"z26q5oFrp6i2aTKLp6Y6jsLESJMoNfZQwk8VKXc37c24bJPj5fwBoUEsqv51ADbnUNM\"\n    }\n  }\n}\n";
        let doc: crate::TrustTask<super::Payload> =
            serde_json::from_str(JSON).expect("deserialize request example");
        let rendered = serde_json::to_value(&doc).expect("re-serialize");
        let expected: serde_json::Value = serde_json::from_str(JSON).expect("re-parse expected");
        assert_eq!(rendered, expected, "request example failed round-trip");
    }
    #[test]
    fn response_example_1() {
        const JSON: &str = "{\n  \"id\": \"urn:uuid:00000000-0000-4000-8000-000000000002\",\n  \"type\": \"https://trusttasks.org/spec/vetting/attestation/0.1#response\",\n  \"issuer\": \"did:example:applicant\",\n  \"recipient\": \"did:example:vetter\",\n  \"issuedAt\": \"2026-09-20T14:31:02Z\",\n  \"threadId\": \"urn:uuid:00000000-0000-4000-8000-0000000000ff\",\n  \"payload\": {\n    \"accepted\": true,\n    \"heldCount\": 2\n  }\n}\n";
        let doc: crate::TrustTask<super::Response> =
            serde_json::from_str(JSON).expect("deserialize response example");
        let rendered = serde_json::to_value(&doc).expect("re-serialize");
        let expected: serde_json::Value = serde_json::from_str(JSON).expect("re-parse expected");
        assert_eq!(rendered, expected, "response example failed round-trip");
    }
}
